<?php
if (!defined("APP_FOLDER")) exit("No direct script access allowed");
require 'vendor/autoload.php';

use PhpOffice\PhpSpreadsheet\IOFactory;
use Dompdf\Dompdf;
use Dompdf\Options;

if (isset($_POST["add_excel"])) {
	setRules("start_date", "Zeitraum beginn", "required");
	setRules("end_date", "Zeitraum ende", "required");

	if (validation()) {
		$fileName = $_FILES["excel_sheet"]["name"];
		$fileType = $_FILES["excel_sheet"]["type"];
		$fileExtension = pathinfo($fileName, PATHINFO_EXTENSION);
		$allowedMimeTypes = [
			'application/vnd.ms-excel',
			'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
			'text/csv'
		];

		$allowedExtensions = ['xls', 'xlsx', 'csv'];

		if (!in_array($fileType, $allowedMimeTypes)) {
			setMsg("Error: Only Excel (XLS, XLSX) and CSV files are allowed based on MIME type.", 1);
			redirect();
		} else if (!in_array(strtolower($fileExtension), $allowedExtensions)) {
			setMsg("Error: Only Excel (XLS, XLSX) and CSV files are allowed based on file extension.", 1);
			redirect();
		} else {
			try {
				$filePath = $_FILES['excel_sheet']['tmp_name'];
				$spreadsheet = IOFactory::load($filePath);
				$sheet = $spreadsheet->getActiveSheet();
				$total_amount = 0;
				$excel_date = "";

				// $invoice_list_location = [];

				$match_excel_columns = [
					'A' => 'invoice_list_order_no',
					'B' => 'invoice_list_machine_no',
					'C' => 'invoice_list_machine_name',
					'D' => 'invoice_list_dealer',
					'E' => 'invoice_list_goods_name',
					'F' => 'invoice_list_amount',
					'G' => 'invoice_list_payment_method',
					'H' => 'invoice_list_order_status',
					'I' => 'invoice_list_ship_status',
					'J' => 'invoice_list_refund_status',
					'K' => 'invoice_list_order_time',
					'L' => 'invoice_list_ship_time',
					'M' => 'invoice_list_refund_time',
				];

				foreach ($match_db_columns as $field) {
					${$field} = [];
				}

				$match_db_columns = [
					'order_number' => 'invoice_list_order_no',
					'machine_no' => 'invoice_list_machine_no',
					'machine_name' => 'invoice_list_machine_name',
					'dealer' => 'invoice_list_dealer',
					'goods_name' => 'invoice_list_goods_name',
					'amount' => 'invoice_list_amount',
					'payment_method' => 'invoice_list_payment_method',
					'order_status' => 'invoice_list_order_status',
					'ship_status' => 'invoice_list_ship_status',
					'refund_status' => 'invoice_list_refund_status',
					'order_time' => 'invoice_list_order_time',
					'ship_time' => 'invoice_list_ship_time',
					'refund_time' => 'invoice_list_refund_time',
				];


				foreach ($sheet->getRowIterator() as $key => $row) {
					$cellIterator = $row->getCellIterator();
					$cellIterator->setIterateOnlyExistingCells(FALSE);
					if ($key > 3) {
						foreach ($cellIterator as $cell_key => $cell) {
							${$match_excel_columns[$cell_key]}[] = $cell->getValue();
							if ($match_excel_columns[$cell_key] == 'invoice_list_amount') {
								$total_amount += $cell->getValue();
							}
						}
					} else {
						foreach ($cellIterator as $cell_key => $cell) {
							if ($cell_key == "A" && $key == 2) {
								$excel_date = $cell->getValue();
								$date_array = explode("-", $cell->getValue());
								if (isset($date_array[0]) && isset($date_array[1])) {
									$excel_date = $date_array[1] . $date_array[0];
								}
							}
						}
					}
				}

				$data_invoice = [];
				$data_invoice['start_date'] = $_POST['start_date'];
				$data_invoice['end_date'] = $_POST['end_date'];
				$data_invoice['excel_date'] = $excel_date;
				$data_invoice['total_amount'] = $total_amount;
				$data_invoice['created_at'] = date("Y-m-d H:i:s");
				$data_invoice['created_by'] = getLoginId();
				$invoice_id = insert("invoice2", $data_invoice);

				foreach ($invoice_list_machine_no as $key => $val) {
					$data_invoice_list = [];
					$data_invoice_list['invoice_id'] = $invoice_id;
					$data_invoice_list['machine_no'] = $val;

					// $data_invoice_list['location'] = $invoice_list_location[$key] ?? null;
					foreach ($match_db_columns as $db_column => $excel_field) {
						$data_invoice_list[$db_column] = ${$excel_field}[$key] ?? null;
					}
					insert("invoice_list2", $data_invoice_list);
				}
				setMsg("Add excel successfully.");
				redirect("abrechnung_gesamt/" . base64_encode($invoice_id));
			} catch (\Exception $ex) {
				die($ex->getMessage());
			}
		}
	}
}

if (isset($page_var1)) {
	try {
		$invoice_id = base64_decode($page_var1);
		$invoice = selectById('invoice2', $invoice_id);
		$invoice_list = select('invoice_list2', "invoice_id = '$invoice_id'");
		$case_amount = 0;
		$card_amount = 0;

		$grouped_invoice_list = [];
		foreach ($invoice_list as $key => $row) {
			if (strtolower($row['payment_method']) == 'card') {
				$card_amount += $row['amount'];
			} elseif (strtolower($row['payment_method']) == 'cash') {
				$case_amount += $row['amount'];
			}

			$grouped_invoice_list[$row['machine_no']][] = $row;
		}

		$pdf_invoice_list = [];
		foreach ($grouped_invoice_list as $machine_no => $rows) {
			$total_amount = 0;
			$machine_name = '';
			$dealer = '';
			foreach ($rows as $row) {
				$total_amount += $row['amount'];
				if (empty($machine_name)) {
					$machine_name = $row['machine_name'];
				}
				if (empty($dealer)) {
					$dealer = $row['dealer'];
				}
			}
			
			$pdf_invoice_list[] = [
				'machine_no' => $machine_no,
				'machine_name' => $machine_name,
				'dealer' => $dealer,
				'amount' => $total_amount,
				'orders' => count($rows),
			];
		}


		$options = new Options();
		$options->set('defaultFont', 'DejaVu Sans');
		$options->set('isHtml5ParserEnabled', true);
		$options->set('isRemoteEnabled', true);
		$dompdf = new Dompdf($options);

		$table_data = '<table class="product-table" border="1px" >';
		$table_data .= "<tr>";
		$table_data .= "<th>Maschinen-Nr</th>";
		$table_data .= "<th>Standort</th>";
		$table_data .= "<th>Händler</th>";
		$table_data .= "<th>Bestellungen</th>";
		$table_data .= "<th>Betrag (€)</th>";
		$table_data .= "</tr>";

		$monthsAbbr = ["Jan" => "Jan", "Feb" => "Feb", "Mar" => "Mär", "Apr" => "Apr", "May" => "Mai", "Jun" => "Jun", "Jul" => "Jul", "Aug" => "Aug", "Sep" => "Sep", "Oct" => "Okt", "Nov" => "Nov", "Dec" => "Dez"];

		$start_date_m = date("M", strtotime($invoice['start_date']));
		$start_date = date("d", strtotime($invoice['start_date']));
		$start_date .= ' ' . $monthsAbbr[$start_date_m] . ', ';
		$start_date .= date("Y", strtotime($invoice['start_date']));

		$end_date_m = date("M", strtotime($invoice['end_date']));
		$end_date = date("d", strtotime($invoice['end_date']));
		$end_date .= ' ' . $monthsAbbr[$end_date_m] . ', ';
		$end_date .= date("Y", strtotime($invoice['end_date']));

		$show_date = $start_date . ' - ' . $end_date;

		$total_amount = $invoice['total_amount'];

		foreach ($pdf_invoice_list as $k => $row) {
			$table_data .= "<tr>";
			$table_data .= "<td>" . $row['machine_no'] . "</td>";
			$table_data .= "<td>" . $row['machine_name'] . "</td>";
			$table_data .= "<td>" . $row['dealer'] . "</td>";
			$table_data .= "<td>" . $row['orders'] . "</td>";
			$table_data .= "<td>" . number_format($row['amount'], 2, ',', '') . " €</td>";
			$table_data .= "</tr>";
		}

		$table_data .= "<tr class='bg-gray'>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td>Gesamtsumme</td>";
		$table_data .= "<td>" . number_format($total_amount, 2, ',', '') . " € </td>";
		$table_data .= "</tr>";

		$table_data .= "<tr class='bg-gray'>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td>MwSt (7%)</td>";
		$table_data .= "<td>" . number_format((($total_amount * 7) / 100), 2, ',', '') . " € </td>";
		$table_data .= "</tr>";

		$table_data .= "<tr class='bg-gray'>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td>Bar</td>";
		$table_data .= "<td>" . number_format($card_amount, 2, ',', '') . " € </td>";
		$table_data .= "</tr>";

		$table_data .= "<tr class='bg-gray'>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td></td>";
		$table_data .= "<td>Karte</td>";
		$table_data .= "<td>" . number_format($case_amount, 2, ',', '') . " € </td>";
		$table_data .= "</tr>";

		$table_data .= '</table>';

		$html = '
							<html>
								<head>
									<meta charset="UTF-8">
									<style>
										body {
											font-size: 12px;
											color:#000;
										}

										.img-div {
											text-align: right;
										}

										.product-table {
											width: 100%;
											border-collapse: collapse;
											border: 1px solid #000;
										}

										.product-table th, .product-table td {
											text-align: center;
											font-size: 12px;
											padding: 3px;
											border: 1px solid #000;
										}

										.product-table th {
											background-color: #4f81bd;
											color: #fff;
											font-weight: bold;
										}

										.bg-gray {
											background-color: #d9d9d9;
											font-weight: bold;
										}

										h1 {
											text-align: center;
										}
										.pdf-footer {
											position: fixed;
											bottom: 0;
											left: 0;
											right: 0;
											height: 0px;
											font-size: 10px;
											text-align: center;
											color: #000;
											line-height: 1.5;
										}
									</style>
								</head>
								<body>
									<div class="img-div">
										<img src="data:image/jpeg;base64," width="200px" />
									</div>
									<br/><br/>
									<table width="100%" >
										<tr>							
											<td align="left"><b>C.A.E GmbH</b><br/>Industriestr.10 <br/>59192 Bergkamen</td>
											<td align="right">Zeitraum.: '.$show_date.'</td>
										</tr>
									</table>
									<h1>Verkaufsstatistik</h1>
									'.$table_data.'
									<div class="pdf-footer">
									C.A.E GmbH &#8226; Industriestr.10 &#8226; 59192 Bergkamen<br>
									Amtsgericht Hamm &#8226; Handelsregister: HRB 9444 &#8226; Finanzamt Hamm &#8226; Steuernr.: 322/5729/6261
									</div>
								</body>
							</html>';
			
			$dompdf->loadHtml($html);
			$dompdf->setPaper('A4', 'portrait');
			$dompdf->render();

			if(isset($_GET['is_download']) && $_GET['is_download'] = "yes") {
				$dompdf->stream("verkaufsstatistik_".$invoice_id.".pdf", ["Attachment" => true]);
			}else{			
				$dompdf->stream("verkaufsstatistik_".$invoice_id.".pdf", ["Attachment" => false]);
			}
		} catch (\Exception $ex) {
			die($ex->getMessage());
		}
	}
?>
